# ============ size formatting ============
def format_size(size_bytes, output_format):
    # output_format is None (default) or one of si,b,k,m,g,t,kb,mb,gb,tb
    # size_bytes is int (could be 0)
    # For filecount mode, size is count, handled separately (just str)
    # For normal, use human readable
    if output_format is None:
        # default 1024-based auto
        return format_human(size_bytes, 1024)
    of=output_format
    if of=="si":
        return format_human(size_bytes, 1000)
    elif of=="b":
        return f"{size_bytes}B"
    elif of=="k":
        return f"{size_bytes//1024}K"
    elif of=="kb":
        return f"{size_bytes//1000}K"
    elif of=="m":
        return f"{size_bytes//(1024*1024)}M"
    elif of=="mb":
        return f"{size_bytes//1000000}M"
    elif of=="g":
        return f"{size_bytes//(1024*1024*1024)}G"
    elif of=="gb":
        return f"{size_bytes//1000000000}G"
    elif of=="t":
        return f"{size_bytes//(1024*1024*1024*1024)}T"
    elif of=="tb":
        return f"{size_bytes//1000000000000}T"
    else:
        return format_human(size_bytes, 1024)

def format_human(size, divisor):
    # divisor 1024 or 1000
    # units B,K,M,G,T,P (max P)
    units=["B","K","M","G","T","P"]
    if size < divisor:
        return f"{size}B"
    # Find unit
    val=float(size)
    idx=0
    # divisor loop: while val >= divisor and idx < len-1? But need to handle P cap: if val >= divisor and idx==5 (P), stay at P (show large value)
    # Actually for size >= divisor^(len), stay at P with large val
    # Implementation: divide until val < divisor or idx==5
    # Start with B (idx0), K(idx1), etc.
    # For size=1048576, divisor1024: val=1048576 -> /1024=1024 (idx1 K, val1024) -> since val>=1024 and idx<5, /1024=1.0 (idx2 M) -> val<1024 stop => 1.0M
    # For size=1152921504606846976 (1024^6), divisor1024: val huge -> divide 5 times to P with val1024 => idx5 P, val1024 >=1024 but idx==5 cap, stop => 1024P
    # Good.
    # Need to track idx correctly.
    # Start idx=0 (B), val=size
    # While val >= divisor and idx < 5:
    #   val/=divisor; idx+=1
    # But for size=1023, divisor1024: val1023<1024 => idx0 B => "1023B" correct.
    # For size=1000, divisor1000 (si): val1000>=1000 => val=1.0 idx1 K => "1.0K" correct.
    # For size=999, divisor1000: val999<1000 => "999B" correct.
    val=float(size)
    idx=0
    while val>=divisor and idx<5:
        val/=divisor
        idx+=1
    unit=units[idx]
    if unit=="B":
        # Should not happen since size>=divisor, but for safety
        return f"{int(val)}B"
    if val<10:
        # one decimal, rounded
        # Use round half away? Python round uses bankers. Need to match dust's rounding (which uses format with one decimal, likely round half away?).
        # For 9.95K case: 10189/1024=9.950... -> 10.0K (rounded). Python f"{9.950:.1f}" => '10.0'? Let's test: 9.950... with round half even? 9.95 with one decimal? Actually 9.950... to one decimal: 10.0 (since second decimal 5+). Python round(9.950,1)=10.0? Should be.
        # For 1.049... ->1.0, 1.050...->1.1? Python: 1.0507->1.1? Yes.
        # We'll use formatting with:.1f which uses round half even? For .05 cases, bankers might differ, but rare.
        s=f"{val:.1f}{unit}"
        return s
    else:
        # integer, truncated (floor) not rounded! As observed: 10.5K->10K, 15.5K->15K.
        # So int(val) truncates toward zero (floor for positive).
        s=f"{int(val)}{unit}"
        return s

def parse_min_size(s):
    # Returns threshold int, and whether to warn (True if invalid with warning)
    # s is string
    orig=s
    s=str(s).strip()
    if s=="":
        return 0, False
    # Match leading digits
    m=re.match(r'^(\d+)(.*)$', s, re.DOTALL)
    if not m:
        return 0, False
    num_str, rest=m.groups()
    try:
        num=int(num_str)
    except:
        return 0, False
    if rest=="":
        return num, False
    if rest[0]==" " or rest[0]=="\t":
        # space after digits => ignore rest, threshold=num, no warn
        return num, False
    # rest starts with non-space
    # If rest[0] is not alpha? e.g., ".", ",", etc. => threshold=num, no warn
    if not rest[0].isalpha():
        return num, False
    # rest starts with alpha: check valid
    # Valid first chars: B,K,M,G,T,P (case-insensitive)
    first=rest[0].upper()
    if first not in ("B","K","M","G","T","P"):
        return 0, True
    # Valid first char, determine multiplier
    # Need to distinguish K vs KB, etc.
    # If rest length>=2 and rest[1].upper()=="B" and first in ("K","M","G","T","P"):
    #   then it's KB/MB/... => 1000-based
    # Else if first=="B": mult=1 (ignore rest? e.g., "BB"? Still 1)
    # Else (K,M,G,T,P without B): mult=1024-based
    # For "KK", rest="KK", first K, second K !=B => 1024
    # For "K2", rest="K2", second 2 !=B =>1024
    # For "KBX", rest="KBX", first K, second B =>1000 (ignore X)
    # Good.
    if first=="B":
        return num, False
    # K,M,G,T,P
    if len(rest)>=2 and rest[1].upper()=="B":
        # 1000-based
        if first=="K":
            mult=1000
        elif first=="M":
            mult=1000000
        elif first=="G":
            mult=1000000000
        elif first=="T":
            mult=1000000000000
        elif first=="P":
            mult=1000000000000000
        else:
            mult=1
    else:
        # 1024-based
        if first=="K":
            mult=1024
        elif first=="M":
            mult=1024*1024
        elif first=="G":
            mult=1024*1024*1024
        elif first=="T":
            mult=1024*1024*1024*1024
        elif first=="P":
            mult=1024*1024*1024*1024*1024
        else:
            mult=1
    return num*mult, False

PYEOF
