    # For "KBX", rest="KBX", first K, second B =>1000 (ignore X)
    # Good.
    if first=="B":
        return num, False
    # K,M,G,T,P
    if len(rest)>=2 and rest[1].upper()=="B":
        # 1000-based
        if first=="K":
            mult=1000
        elif first=="M":
            mult=1000000
        elif first=="G":
            mult=1000000000
        elif first=="T":
            mult=1000000000000
        elif first=="P":
            mult=1000000000000000
        else:
            mult=1
    else:
        # 1024-based
        if first=="K":
            mult=1024
        elif first=="M":
            mult=1024*1024
        elif first=="G":
            mult=1024*1024*1024
        elif first=="T":
            mult=1024*1024*1024*1024
        elif first=="P":
            mult=1024*1024*1024*1024*1024
        else:
            mult=1
    return num*mult, False

