# ===== REST: display + main =====

class DispEntry2:
    __slots__=("node","depth","is_first","is_last","anc","is_expanded")
    def __init__(self, node, depth, is_first, is_last, anc, is_expanded):
        self.node=node
        self.depth=depth
        self.is_first=is_first
        self.is_last=is_last
        self.anc=anc
        self.is_expanded=is_expanded

def build_hierarchy_filtered(root_node, opts, collapse_set, depth_limit, min_thresh):
    only_dir = opts.get("only-dir", False)
    # only_file handled separately via flatten, so here assume not only_file
    def rec(node, depth):
        is_root = (depth==0)
        if depth_limit is not None and depth > depth_limit:
            return None
        if not is_root and min_thresh is not None and node.size <= min_thresh:
            return None
        if only_dir and not node.is_dir and not is_root:
            return None
        try:
            ap=os.path.normpath(os.path.abspath(node.path))
        except:
            ap=node.path
        collapsed = ap in collapse_set and node.is_dir
        if node.is_dir and not collapsed:
            new_children=[]
            for ch in node.children:
                r=rec(ch, depth+1)
                if r is not None:
                    new_children.append(r)
            nn=Node(node.path, node.name, node.is_dir, node.is_symlink, size=node.size, children=new_children)
            nn.stat_res=getattr(node,'stat_res',None)
            nn.filetime=getattr(node,'filetime',None)
            return nn
        else:
            nn=Node(node.path, node.name, node.is_dir, node.is_symlink, size=node.size, children=[])
            nn.stat_res=getattr(node,'stat_res',None)
            nn.filetime=getattr(node,'filetime',None)
            return nn
    return rec(root_node, 0)

def collect_flat_files(root_node, depth_limit, min_thresh):
    res=[]
    def dfs(node, depth):
        if depth_limit is not None and depth>depth_limit:
            return
        if node.is_dir:
            for ch in node.children:
                dfs(ch, depth+1)
        else:
            if min_thresh is not None and node.size <= min_thresh:
                return
            res.append(node)
    dfs(root_node, 0)
    return res

def prune_hierarchy(root_hier, n_limit, skip_total):
    if n_limit is None:
        return root_hier
    limit = n_limit + (0 if skip_total else 1)
    def count(node, is_root):
        if skip_total and is_root:
            c=0
            for ch in node.children:
                c+=count(ch, False)
