                        lst=os.lstat(p)
                        is_link=stat.S_ISLNK(lst.st_mode)
                    except:
                        is_link=False
                    if is_link:
                        try:
                            if os.path.isdir(p):
                                name_c=f"\x1b[1;34m{name_raw}\x1b[0m"
                        except:
                            pass
                    else:
                        if e.node.is_dir:
                            name_c=f"\x1b[1;34m{name_raw}\x1b[0m"
                        else:
                            try:
                                st=os.stat(p)
                                if stat.S_ISREG(st.st_mode) and (st.st_mode & 0o111):
                                    name_c=f"\x1b[1;32m{name_raw}\x1b[0m"
                            except:
                                pass
                except:
                    pass
            if e.depth==0:
                line=f"{sz_c} {tree} {name_c}"
            else:
                line=f"{sz_c}   {tree} {name_c}"
            lines.append(line)
        return lines
    usable=bar_len-1
    E_list=[]
    for e in entries:
        if total_for_pct==0:
            E=1
        else:
            if e.node.size==0:
                E=1
            else:
                E=int(math.ceil(e.node.size/total_for_pct*usable))
                if E<1:
                    E=1
                if E>usable:
                    E=usable
        E_list.append(E)
    lines=[]
    for idx,e in enumerate(entries):
        sz_pad=size_padded[idx]
        tree=tree_strs[idx]
        name_raw=raw_names[idx]
        left_raw=left_raws[idx]
        pad_len=max_left_len - len(left_raw)
        sz_c=sz_pad
        name_c=name_raw
        if use_colors:
            if id(e.node) in largest_ids:
                sz_c=f"\x1b[31m{sz_pad}\x1b[0m"
            try:
                p=e.node.path
                try:
                    lst=os.lstat(p)
                    is_link=stat.S_ISLNK(lst.st_mode)
                except:
                    is_link=False
                if is_link:
                    try:
                        if os.path.isdir(p):
                            name_c=f"\x1b[1;34m{name_raw}\x1b[0m"
                    except:
                        pass
                else:
                    if e.node.is_dir:
                        name_c=f"\x1b[1;34m{name_raw}\x1b[0m"
                    else:
                        try:
                            st=os.stat(p)
                            if stat.S_ISREG(st.st_mode) and (st.st_mode & 0o111):
                                name_c=f"\x1b[1;32m{name_raw}\x1b[0m"
                        except:
                            pass
            except:
                pass
        if e.depth==0:
            left_colored=f"{sz_c} {tree} {name_c}"
        else:
            left_colored=f"{sz_c}   {tree} {name_c}"
        left_colored_padded=left_colored + (" "*pad_len)
        E=E_list[idx]
        if bars_right:
            bar_content=" "*(usable-E) + "█"*E
        else:
            bar_content="█"*E + " "*(usable-E)
        bar_field=bar_content + " "
        pct=pct_strs[idx]
        line=f"{left_colored_padded}│{bar_field}│{pct}"
        lines.append(line)
    return lines
